import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final quantidade=TextEditingController();int estoque=0;String mensagem='';void entrada(){final q=int.tryParse(quantidade.text);if(q==null||q<=0){setState(()=>mensagem='Informe uma quantidade inteira positiva.');return;}setState((){estoque+=q;mensagem='Entrada realizada com sucesso.';});}void saida(){final q=int.tryParse(quantidade.text);if(q==null||q<=0){setState(()=>mensagem='Informe uma quantidade inteira positiva.');return;}if(q>estoque){setState(()=>mensagem='Saída não realizada: quantidade maior que o estoque disponível.');return;}setState((){estoque-=q;mensagem='Saída realizada com sucesso.';});}void limparCampo(){quantidade.clear();setState(()=>mensagem='');}@override void dispose(){quantidade.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Controle de estoque')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Text('Quantidade atual em estoque: $estoque',style:const TextStyle(fontSize:18)),const SizedBox(height:24),TextField(controller:quantidade,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantidade')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:entrada,child:const Text('Entrada')),const SizedBox(width:8),ElevatedButton(onPressed:saida,child:const Text('Saída')),const SizedBox(width:8),ElevatedButton(onPressed:limparCampo,child:const Text('Limpar campo'))]),const SizedBox(height:24),Text(mensagem)])));}
